//! How `pi --mode rpc` is launched: the user's launch arguments checked against what T3 Code owns, and the
//! T3-owned extension that carries the permission hook and the T3 MCP bridge. Mirrors `piT3McpInjection.ts`.
//! The extension source is the original's `PI_T3_MCP_EXTENSION_SOURCE`, generated by
//! `tools/generate_pi_extension_source.mjs` and written to the cache directory when a session opens.
use std::{collections::HashMap, path::{Path, PathBuf}};

pub const EXTENSION_FILENAME: &str = "pi-t3-mcp-extension.ts";
pub const EXTENSION_SOURCE: &str = include_str!("pi-t3-mcp-extension.ts");
pub const MCP_URL_ENV: &str = "T3_MCP_URL";
pub const MCP_BEARER_ENV: &str = "T3_MCP_BEARER_TOKEN";
pub const RUNTIME_MODE_ENV: &str = "T3_PI_RUNTIME_MODE";
/// `PI_FILE_CHANGE_TOOLS`: the tools whose confirmations are file-change approvals.
pub const FILE_CHANGE_TOOLS: [&str; 2] = ["edit", "write"];

const RESERVED: &[&str] = &[
    "--continue", "-c", "--export", "--fork", "--help", "-h", "--list-models", "--mode", "--no-session", "--print", "-p", "--resume", "-r", "--session", "--session-id", "--version", "-v",
];
const WITH_VALUES: &[&str] = &[
    "--api-key", "--append-system-prompt", "--exclude-tools", "-xt", "--extension", "-e", "--model", "--models", "--name", "-n", "--prompt-template", "--provider", "--session-dir", "--skill", "--system-prompt", "--theme", "--thinking", "--tools", "-t", "--tui-mode", "--use-theme",
];
const WITHOUT_VALUES: &[&str] = &[
    "--approve", "-a", "--no-approve", "-na", "--no-builtin-tools", "-nbt", "--no-context-files", "-nc", "--no-extensions", "-ne", "--no-prompt-templates", "-np", "--no-skills", "-ns", "--no-themes", "--no-tools", "-nt", "--offline", "--verbose",
];

fn reserved_argument(arg: &str) -> Option<&'static str> {
    RESERVED.iter().copied().find(|reserved| arg == *reserved || (reserved.starts_with("--") && arg.starts_with(&format!("{reserved}="))))
}
/// Pi parses equals-form tokens only as extension flags, even when their name matches a built-in option.
/// Known built-ins are split; arbitrary extension flags keep their native form.
fn normalize_equals(args: Vec<String>) -> Vec<String> {
    args.into_iter()
        .flat_map(|arg| match arg.find('=') {
            Some(at) if at > 0 && WITH_VALUES.contains(&&arg[..at]) => vec![arg[..at].to_owned(), arg[at + 1..].to_owned()],
            _ => vec![arg],
        })
        .collect()
}

/// `resolvePiLaunchArgs`. T3 owns RPC mode and session identity, so arguments that select a different
/// execution mode or native session are rejected before spawn; the message says which.
pub fn resolve_launch_args(launch_args: &str) -> Result<Vec<String>, String> {
    let args = normalize_equals(crate::codex::tokenize_cli_args(launch_args));
    let (mut has_provider, mut has_model) = (false, false);
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if let Some(reserved) = reserved_argument(arg) {
            return Err(format!("Pi launch argument '{reserved}' is controlled by T3 Code and cannot be overridden."));
        }
        if arg == "--" {
            return Err("Pi launch arguments cannot include positional prompts.".into());
        }
        if WITH_VALUES.contains(&arg.as_str()) {
            if args.get(index + 1).is_none() {
                return Err(format!("Pi launch argument '{arg}' requires a value."));
            }
            has_provider |= arg == "--provider";
            has_model |= arg == "--model";
            index += 2;
            continue;
        }
        if WITHOUT_VALUES.contains(&arg.as_str()) || (arg.starts_with("--") && arg.contains('=')) {
            index += 1;
            continue;
        }
        if arg.starts_with("--") {
            // Pi extensions may register arbitrary long flags. One following non-flag token is that flag's value.
            if args.get(index + 1).is_some_and(|next| !next.starts_with('-') && !next.starts_with('@')) {
                index += 1;
            }
            index += 1;
            continue;
        }
        if arg.starts_with('-') {
            return Err(format!("Pi launch argument '{arg}' is not supported by T3 Code."));
        }
        return Err(format!("Pi launch arguments cannot include positional prompt '{arg}'."));
    }
    // Pi 1.0 exits at startup on `--provider` without `--model`; older versions silently ran another provider's default.
    if has_provider && !has_model {
        return Err("Pi launch argument '--provider' requires '--model'.".into());
    }
    Ok(args)
}

fn normalized_path(value: &str) -> String {
    value.replace('\\', "/").trim_end_matches('/').to_owned()
}
fn has_explicit_extension(args: &[String], extension_path: &str) -> bool {
    let wanted = normalized_path(extension_path);
    let mut index = 0;
    while index < args.len() {
        if args[index] == "--extension" || args[index] == "-e" {
            if args.get(index + 1).is_some_and(|configured| normalized_path(configured) == wanted) {
                return true;
            }
            index += 1;
        }
        index += 1;
    }
    false
}

/// What `buildPiRpcLaunch` decided.
pub struct RpcLaunch {
    pub args: Vec<String>,
    /// Added to the process environment.
    pub env: HashMap<String, String>,
    /// Removed from it: these belong to the current T3 session, and a Pi child never reuses credentials
    /// inherited from the server or a parent provider process.
    pub remove_env: Vec<String>,
}
pub struct LaunchOptions<'a> {
    pub launch_args: &'a [String],
    pub mcp: Option<(&'a str, &'a str)>,
    pub extension_path: Option<&'a str>,
    pub ephemeral: bool,
    pub runtime_mode: Option<&'a str>,
}
/// `buildPiRpcLaunch`.
pub fn build_rpc_launch(options: &LaunchOptions) -> RpcLaunch {
    let has_extension = options.extension_path.is_some();
    let mut args: Vec<String> = vec!["--mode".into(), "rpc".into()];
    if options.ephemeral {
        args.push("--no-session".into());
    }
    args.extend(options.launch_args.iter().cloned());
    if let Some(extension) = options.extension_path {
        if !has_explicit_extension(&args, extension) {
            args.extend(["--extension".into(), extension.to_owned()]);
        }
    }
    let mut env = HashMap::new();
    if let (true, Some(mode)) = (has_extension, options.runtime_mode) {
        env.insert(RUNTIME_MODE_ENV.into(), if mode == "auto" { "approval-required" } else { mode }.to_owned());
    }
    if let (true, Some((endpoint, authorization))) = (has_extension, options.mcp) {
        env.insert(MCP_URL_ENV.into(), endpoint.to_owned());
        env.insert(MCP_BEARER_ENV.into(), authorization.strip_prefix("Bearer ").unwrap_or(authorization).to_owned());
    }
    RpcLaunch { args, env, remove_env: vec![MCP_URL_ENV.into(), MCP_BEARER_ENV.into()] }
}

/// `materializePiT3McpExtension`: the extension is rewritten only when the cached copy differs.
pub fn materialize_extension(cache_dir: &Path) -> std::io::Result<PathBuf> {
    std::fs::create_dir_all(cache_dir)?;
    let destination = cache_dir.join(EXTENSION_FILENAME);
    if std::fs::read_to_string(&destination).ok().as_deref() != Some(EXTENSION_SOURCE) {
        std::fs::write(&destination, EXTENSION_SOURCE)?;
    }
    Ok(destination)
}

#[cfg(test)]
mod tests {
    use super::*;
    fn resolve(args: &str) -> Result<Vec<String>, String> {
        resolve_launch_args(args)
    }
    #[test]
    fn launch_arguments_resolve_as_the_original_resolves_them() {
        let rows: Vec<serde_json::Value> = serde_json::from_str(include_str!("../tests/fixtures/pi-functions.json")).unwrap();
        let mut checked = 0;
        for row in rows.iter().filter(|row| row["operation"] == "launch") {
            let actual = match resolve(row["input"]["launchArgs"].as_str().unwrap()) {
                Ok(args) => serde_json::json!({"args":args}),
                Err(message) => serde_json::json!({"message":message}),
            };
            assert_eq!(actual, row["output"], "{row}");
            checked += 1;
        }
        assert!(checked >= 20);
    }
    #[test]
    fn the_launch_arguments_t3_owns_are_rejected_with_the_original_messages() {
        for (input, message) in [
            ("--mode json", "Pi launch argument '--mode' is controlled by T3 Code and cannot be overridden."),
            ("--session=/x", "Pi launch argument '--session' is controlled by T3 Code and cannot be overridden."),
            ("-c", "Pi launch argument '-c' is controlled by T3 Code and cannot be overridden."),
            ("--no-session", "Pi launch argument '--no-session' is controlled by T3 Code and cannot be overridden."),
            ("--fork a", "Pi launch argument '--fork' is controlled by T3 Code and cannot be overridden."),
            ("-- hello", "Pi launch arguments cannot include positional prompts."),
            ("hello", "Pi launch arguments cannot include positional prompt 'hello'."),
            ("-z", "Pi launch argument '-z' is not supported by T3 Code."),
            ("--model", "Pi launch argument '--model' requires a value."),
            ("--provider openrouter", "Pi launch argument '--provider' requires '--model'."),
        ] {
            assert_eq!(resolve(input), Err(message.to_owned()), "{input}");
        }
    }
    #[test]
    fn accepted_arguments_keep_their_form_and_built_in_equals_are_split() {
        let recorded = "--provider openrouter --model deepseek/deepseek-v4-flash --no-extensions --no-skills --no-prompt-templates --no-context-files --approve";
        assert_eq!(resolve(recorded).unwrap(), recorded.split(' ').collect::<Vec<_>>());
        assert_eq!(resolve("--model=a/b --provider=x --foo=bar --flag value --bare").unwrap(), ["--model", "a/b", "--provider", "x", "--foo=bar", "--flag", "value", "--bare"]);
        assert_eq!(resolve("").unwrap(), Vec::<String>::new());
        assert_eq!(resolve("--tools 'read,bash' --offline").unwrap(), ["--tools", "read,bash", "--offline"]);
    }
    #[test]
    fn the_rpc_launch_adds_the_extension_once_and_hands_the_session_its_own_credentials() {
        let launch = build_rpc_launch(&LaunchOptions { launch_args: &["--approve".into()], mcp: Some(("http://127.0.0.1:1/mcp", "Bearer secret-token")), extension_path: Some("/cache/pi-t3-mcp-extension.ts"), ephemeral: false, runtime_mode: Some("auto") });
        assert_eq!(launch.args, ["--mode", "rpc", "--approve", "--extension", "/cache/pi-t3-mcp-extension.ts"]);
        assert_eq!(launch.env[RUNTIME_MODE_ENV], "approval-required");
        assert_eq!((launch.env[MCP_URL_ENV].as_str(), launch.env[MCP_BEARER_ENV].as_str()), ("http://127.0.0.1:1/mcp", "secret-token"));
        assert_eq!(launch.remove_env, [MCP_URL_ENV, MCP_BEARER_ENV]);
        // A user-configured copy of the same extension is not added twice; without a session there is no credential.
        let configured = build_rpc_launch(&LaunchOptions { launch_args: &["-e".into(), "/cache/pi-t3-mcp-extension.ts/".into()], mcp: None, extension_path: Some("/cache/pi-t3-mcp-extension.ts"), ephemeral: true, runtime_mode: Some("full-access") });
        assert_eq!(configured.args, ["--mode", "rpc", "--no-session", "-e", "/cache/pi-t3-mcp-extension.ts/"]);
        assert!(!configured.env.contains_key(MCP_URL_ENV) && configured.env[RUNTIME_MODE_ENV] == "full-access");
        let bare = build_rpc_launch(&LaunchOptions { launch_args: &[], mcp: None, extension_path: None, ephemeral: true, runtime_mode: Some("full-access") });
        assert_eq!((bare.args.as_slice(), bare.env.is_empty()), (&["--mode".to_owned(), "rpc".into(), "--no-session".into()][..], true));
    }
    #[test]
    fn the_extension_is_the_originals_and_is_written_only_when_it_changes() {
        assert!(EXTENSION_SOURCE.contains("@earendil-works/pi-coding-agent") && EXTENSION_SOURCE.contains("T3_PI_RUNTIME_MODE"));
        // The original embeds its orchestration instructions as a JSON string literal.
        let instructions: serde_json::Value = serde_json::from_str(include_str!("provider-instructions.json")).unwrap();
        assert!(EXTENSION_SOURCE.contains(&serde_json::to_string(instructions["orchestration"].as_str().unwrap().trim()).unwrap()));
        let directory = tempfile::tempdir().unwrap();
        let path = materialize_extension(directory.path()).unwrap();
        assert_eq!(std::fs::read_to_string(&path).unwrap(), EXTENSION_SOURCE);
        std::fs::write(&path, "stale").unwrap();
        assert_eq!(materialize_extension(directory.path()).unwrap(), path);
        assert_eq!(std::fs::read_to_string(&path).unwrap(), EXTENSION_SOURCE);
    }
}
